style.css:
@-moz-document domain("youtube.com") {
body::before {
    content: "";
    background: url("https://i.imgur.com/hUzKbMb.jpg") no-repeat center center fixed;
    background-size: cover;
    position: fixed;
    top: 0;
    left: 0;
    height: 100vh;
    width: 100vw;
    z-index: -1;
    opacity: 0.25; /* Puedes aumentar a 0.5 o 0.8 si quieres que se vea más */
    pointer-events: none;
  }

  /* Hacer transparentes las capas oscuras de YouTube */
  html,
  body,
  ytd-app,
  ytd-browse,
  ytd-page-manager,
  #background,
  #content,
  ytd-two-column-browse-results-renderer,
  ytd-rich-grid-renderer {
    background: transparent !important;
  }
}
